from pathlib import Path
p = Path('/home/ubuntu/lumin-candles-store/client/src/pages/Home.tsx')
s = p.read_text()
old = '<div className="map-toolbar"><div className="map-location"><span className="map-pulse" /><span>موقعك الحالي</span></div><span className="map-city">الرياض، السعودية</span></div><div className="fake-map">'
new = '''<div className="map-toolbar"><div className="map-location"><span className="map-pulse" /><span>موقعك الحالي</span></div><span className="map-city">الرياض، السعودية</span></div><div className="map-filters"><label><span>نوع الخدمة</span><select value={mapServiceFilter} onChange={(event) => setMapServiceFilter(event.target.value)}><option value="all">كل الخدمات</option>{services.map((service) => <option key={service.id} value={service.id}>{service.title}</option>)}</select></label><label><span>التقييم</span><select value={mapRatingFilter} onChange={(event) => setMapRatingFilter(event.target.value)}><option value="all">كل التقييمات</option><option value="4.8">٤٫٨ فأعلى</option><option value="4.9">٤٫٩ فأعلى</option></select></label><button className="clear-map-filters" onClick={() => { setMapServiceFilter("all"); setMapRatingFilter("all"); }}>مسح</button></div><div className="fake-map">'''
