s = s.replace(old, new, 1)
old_pins = '<button className="map-pin pin-one" onClick={() => toast("شركة درب الإنقاذ — ٨ دقائق")}><Truck size={15} /></button><button className="map-pin pin-two" onClick={() => toast("ورشة السريع — ١١ دقيقة")}><Wrench size={15} /></button><button className="map-pin pin-three" onClick={() => toast("مساندة للآليات — ١٦ دقيقة")}><Package size={15} /></button>'
new_pins = '''{(mapServiceFilter === "all" || mapServiceFilter === "tow") && <button className="map-pin pin-one" onClick={() => toast("شركة درب الإنقاذ — ٨ دقائق")}><Truck size={15} /></button>}{(mapServiceFilter === "all" || mapServiceFilter === "mobile") && <button className="map-pin pin-two" onClick={() => toast("ورشة السريع — ١١ دقيقة")}><Wrench size={15} /></button>}{(mapServiceFilter === "all" || mapServiceFilter === "heavy") && <button className="map-pin pin-three" onClick={() => toast("مساندة للآليات — ١٦ دقيقة")}><Package size={15} /></button>}{(mapServiceFilter === "all" || mapServiceFilter === "projects") && <button className="map-pin pin-four" onClick={() => toast("حلول مواقع البناء — ٢٢ دقيقة")}><HardHat size={15} /></button>}'''
if old_pins not in s: raise SystemExit('pins marker not found')
s = s.replace(old_pins, new_pins, 1)
s = s.replace('<span><span className="status-dot" /> ١٢ مقدم خدمة متاح الآن</span>', '<span><span className="status-dot" /> {filteredMapProviders.length} مقدم خدمة مطابق</span>', 1)
