styles = css.read_text()
styles += '''\n.map-filters { display: flex; align-items: end; gap: 8px; border-top: 1px solid #d8e3d7; background: #f2f7f1; padding: 10px 16px; }\n.map-filters label { display: grid; min-width: 0; flex: 1; gap: 4px; color: #83948a; font-size: 8px; }\n.map-filters select { min-width: 0; border: 1px solid #d7e4d7; border-radius: 7px; background: white; padding: 6px 7px; color: #4b6557; font-size: 9px; outline: none; }\n.map-filters select:focus { border-color: #9dc36e; }\n.clear-map-filters { padding: 6px 5px; color: #6e8b71; font-size: 9px; white-space: nowrap; }\n.clear-map-filters:hover { color: #254d35; }\n.pin-four { top: 67%; left: 38%; background: #68744b; }\n.tone-slate { background: #e1e7e5; color: #263e3a; }\n@media (max-width: 640px) { .map-filters { padding: 9px 11px; } .map-filters select { font-size: 8px; } }\n'''
